=if(A3="","", 
if(countblank(A3:A)<>countblank(M3:M),"Enter media to use in Minipreps tab",
if(countblank(A3:A)<>countblank(N3:N),"Enter antibiotics to use in Minipreps tab",
if(countblank(A3:A)<>countblank(O3:O),"Enter culture volumes to use in Minipreps tab",
trim("Prepare the following media mixtures:"&char(10)&trim(join(rept(char(160),3),byrow(QUERY( {M3:M,N3:N,arrayformula(value(O3:O)),P3:P}, "select Col1,Col2,sum(Col3) where Col1 is not null and Col4 is null group by Col1,Col2 label Col1 ''" ),lambda(x,let(media,index(x,1),label,index(x,2),val,index(x,3),if(label="","",">"&round(val+settings_mDefaultCultureVolume,-1)&"mL "&media&"-"&label)))))))))))
